-- Cases plugin. Band
-- 0200–0299 (config/plugins.ts). Every table is prefixed with the plugin id,
-- so it can never collide with the core's own legacy "case" / case_event
-- tables, which this plugin does not read or touch.
--
-- Field names are the brain's `case` template frontmatter (mentat-ai-bootstrap
-- reference/templates/case.*.md), so a move between markdown and admin is a
-- field-by-field copy. Dates are ISO calendar dates (YYYY-MM-DD).

CREATE TABLE IF NOT EXISTS cases_case (
  -- ULID, generated by the writer (the agent) so a PUT can be retried.
  id           TEXT PRIMARY KEY NOT NULL CHECK (length(id) = 26),
  title        TEXT NOT NULL CHECK (length(trim(title)) > 0),
  status       TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'waiting', 'done', 'dropped')),
  next_action  TEXT,
  waiting_on   TEXT,
  -- One-off: the deadline. Recurring: the earliest open occurrence, computed
  -- by the API from anchor_at + recurrence and the closed occurrences.
  due_at       TEXT,
  -- monthly:<1-31> | yearly:<MM-DD> | weekly:<mon..sun> | NULL
  recurrence   TEXT,
  -- The first due date of the series; required with a recurrence.
  anchor_at    TEXT,
  category     TEXT,
  brain_ref    TEXT,
  -- Read-only mirror of the brain_ref markdown, uploaded by the agent.
  context      TEXT,
  context_hash TEXT,
  extra        TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extra) AND json_type(extra) = 'object'),
  -- Optimistic lock: every write names the version it read; a mismatch is 409.
  version      INTEGER NOT NULL DEFAULT 1,
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at   TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK (recurrence IS NULL OR anchor_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_cases_case_due ON cases_case (status, due_at);

-- Closed occurrences of a recurring case only. Open ones are computed from
-- the anchor, never pre-generated. One row per (case, date): closing the same
-- date twice cannot produce a second row.
CREATE TABLE IF NOT EXISTS cases_occurrence (
  case_id    TEXT NOT NULL,
  due_at     TEXT NOT NULL,
  status     TEXT NOT NULL CHECK (status IN ('done', 'skipped')),
  done_at    TEXT,
  note       TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (case_id, due_at),
  FOREIGN KEY (case_id) REFERENCES cases_case(id) ON DELETE RESTRICT
);

-- The plugin's audit trail and the agent's change feed (`cases sync` reads
-- it by id cursor). RESTRICT: a case is dropped by status, never deleted.
CREATE TABLE IF NOT EXISTS cases_event (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  case_id        TEXT NOT NULL,
  at             TEXT NOT NULL DEFAULT (datetime('now')),
  actor          TEXT NOT NULL CHECK (actor IN ('user', 'agent')),
  actor_token_id TEXT,
  kind           TEXT NOT NULL,
  body           TEXT,
  FOREIGN KEY (case_id) REFERENCES cases_case(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_cases_event_case ON cases_event (case_id, id);
